function grab(raw) {
  const s = String(raw || '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a < 0 || b < 0) return {};
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return {}; }
}
const src = $input.first().json;
const orig = $('Normalize New Case').first().json || {};
return [{ json: { ...orig, ...src, ...grab(src.output) } }];

const src = $input.first().json;
const pt = String(src.product_type || '').toLowerCase();
let tech = 'General Tech';
if (['crown','bridge','implant crown','implant'].indexOf(pt) >= 0) tech = 'Crown Tech';
else if (['denture','partial'].indexOf(pt) >= 0) tech = 'Denture Tech';
else if (['veneer','night guard','retainer','aligner'].indexOf(pt) >= 0) tech = 'Cosmetic Tech';
let days = null;
if (src.due_date) { const d = new Date(String(src.due_date).slice(0,10) + 'T23:59:59'); if (!isNaN(d.getTime())) days = Math.floor((d.getTime() - Date.now()) / 86400000); }
const rushFlag = String(src.rush || '').toLowerCase() === 'yes';
const miss = Array.isArray(src.missing_items) ? src.missing_items : (src.missing_items ? String(src.missing_items).split(/[;,]/).map(function(x){return x.trim();}).filter(Boolean) : []);
const priority = rushFlag ? 'rush' : (days !== null && days <= 3 ? 'urgent' : 'normal');
return [{ json: { ...src, assigned_tech: tech, days_to_due: days, priority: priority,
  completion: src.completion || 'missing', missing_items: miss.join('; '), missing_list: miss,
  needs_attention: rushFlag || (days !== null && days <= 3) || miss.length > 0, status: 'received', last_update: src.received_at } }];

const body = $json.body || {};
const allowed = ['received','designing','milling','finishing','qc','ready','delivered','remake'];
const raw = String(body.new_status || body.status || '').trim().toLowerCase();
return [{ json: {
  case_id: String(body.case_id || '').trim().toUpperCase(),
  new_status: allowed.indexOf(raw) >= 0 ? raw : '',
  update_note: String(body.note || body.update_note || '').trim(),
  received_at: $now.toISO(),
}}];

const upd = $('Normalize Status Update').first().json;
const rows = $input.all().map(function (i) { return i.json; });
const allowed = ['received','designing','milling','finishing','qc','ready','delivered','remake'];
let match = null;
for (const r of rows) { if (r && String(r.case_id || '').trim().toUpperCase() === upd.case_id) { match = r; break; } }
if (!upd.case_id) { return [{ json: { route: 'notfound', message: 'No case id was supplied.' } }]; }
if (allowed.indexOf(upd.new_status) < 0) { return [{ json: { route: 'badstatus', message: 'Status "' + upd.new_status + '" is not a valid lab stage.', case_id: upd.case_id } }]; }
if (!match) { return [{ json: { route: 'notfound', message: 'No case found with id ' + upd.case_id + '.', case_id: upd.case_id } }]; }
const prev = String(match.status || 'received');
const line = String(upd.case_id) + ' is now ' + upd.new_status + (upd.update_note ? (' | ' + upd.update_note) : '');
return [{ json: {
  route: 'ok', case_id: match.case_id, clinic_name: match.clinic_name || '', clinic_email: match.clinic_email || '',
  patient: match.patient || '', product_type: match.product_type || '', due_date: match.due_date || '',
  rush: match.rush || '', assigned_tech: match.assigned_tech || '', prev_status: prev, new_status: upd.new_status,
  update_note: upd.update_note, changed_at: upd.received_at, status_line: line,
  is_ready: upd.new_status === 'ready', is_delivered: upd.new_status === 'delivered', is_remake: upd.new_status === 'remake',
}}];

const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.case_id; });
const nowMs = Date.now(); const HOUR = 3600000;
const lines = [];
let overdue = 0, dueToday = 0, dueSoon = 0, stuck = 0, readyUnpicked = 0;
for (const r of rows) {
  const st = String(r.status || '').trim();
  if (st === 'delivered' || st === 'remake') continue;
  let dueMs = null;
  if (r.due_date) { const d = new Date(String(r.due_date).slice(0,10) + 'T23:59:59'); if (!isNaN(d.getTime())) dueMs = d.getTime(); }
  const lastUp = r.last_update ? new Date(r.last_update).getTime() : nowMs;
  const daysToDue = dueMs !== null ? ((dueMs - nowMs) / 86400000) : null;
  const ageHours = Math.max(0, Math.round((nowMs - lastUp) / HOUR));
  const lab = '(case ' + r.case_id + ', ' + (r.clinic_name || 'n/a') + ', ' + (r.product_type || 'n/a') + ')';
  if (dueMs !== null && daysToDue < 0) { overdue++; lines.push('OVERDUE ' + lab + ' due ' + Math.abs(Math.round(daysToDue)) + 'd ago, status ' + st); }
  else if (dueMs !== null && daysToDue <= 1) { dueToday++; lines.push('DUE TODAY/TOMORROW ' + lab + ' in ' + Math.max(0, Math.round(daysToDue)) + 'd, status ' + st); }
  else if (dueMs !== null && daysToDue <= 3) { dueSoon++; lines.push('DUE SOON ' + lab + ' in ' + Math.round(daysToDue) + 'd, status ' + st); }
  if (st === 'ready' && dueMs !== null) readyUnpicked++;
  if (st !== 'ready' && ageHours >= 48) { stuck++; lines.push('STUCK ' + lab + ' no update in ' + ageHours + 'h'); }
}
return [{ json: { today: $now.toFormat('yyyy-MM-dd'), active_cases: rows.length, overdue: overdue, due_today: dueToday,
  due_soon: dueSoon, stuck: stuck, ready_unpicked: readyUnpicked, has_overdue: overdue > 0, has_items: lines.length > 0,
  lines: lines, lines_text: lines.join(String.fromCharCode(10)) } }];

