}
const src = $input.first().json;
const orig = $('Compute Board Brief').first().json || {};
return [{ json: { ...orig, ...src, ...grab(src.output) } }];

const src = $input.first().json;
const out = '## ' + (src.headline || 'Lab board brief') + String.fromCharCode(10) + String.fromCharCode(10) +
  (src.digest || '') + String.fromCharCode(10) + String.fromCharCode(10) + 'First action: ' + (src.top_action || '') +
  String.fromCharCode(10) + String.fromCharCode(10) + '---' + String.fromCharCode(10) + (src.lines_text || '');
return [{ json: { ...src, brief_text: out } }];
